function wrAcquireGuestSession(j, src, input, userAgent, state, allowCaptcha) {
    var featureResponse = j.get("https://i.weread.qq.com/feature?synckey=0", wrMap(wrBaseHeaderObject(userAgent)), 30000);
    var feature = wrResponseJson(featureResponse, "游客配置").data;
    var guestToken = feature && feature.feature ? String(feature.feature.guest_token || "") : "";
    if (!guestToken) throw new Error("游客配置缺少 guest_token");
    var guestTimestamp = Math.floor(Number(Packages.java.lang.System.currentTimeMillis()) / 1000);
    var guestRandom = state.random.nextInt(2147483647);
    var guestBody = {
        appFirstInstall:0,
        deviceId:state.oldDeviceId,
        installId:state.installId,
        newDeviceId:state.newDeviceId,
        random:guestRandom,
        signature:wrGuestSignature(j, guestToken, guestRandom, guestTimestamp, state.oldDeviceId),
        timestamp:guestTimestamp,
        virtualChannelId:""
    };
    var guestBodyText = JSON.stringify(guestBody);
    var guest = null;
    var captcha = {ticket:"", randstr:""};
    var challenged = false;
    try {
        var preflight = j.post("https://i.weread.qq.com/guestLogin", guestBodyText,
            wrLoginHeaderMap(userAgent, "", ""), 30000);
        var preflightResult = wrResponseJson(preflight, "游客预登录", true);
        if (preflightResult.status == 200) {
            guest = preflightResult.data;
        } else if (preflightResult.status == 499 && Number(preflightResult.data.errcode) == -2041) {
            challenged = true;
        } else {
            throw new Error("游客预登录失败，HTTP " + preflightResult.status +
                (preflightResult.data.errcode != null ? "，错误码 " + preflightResult.data.errcode : ""));
        }
    } catch (preflightError) {
        var detail = String(preflightError && preflightError.message ? preflightError.message : preflightError);
        if (detail.indexOf("499") >= 0 || detail.indexOf("-2041") >= 0) challenged = true;
        else throw preflightError;
    }
    if (guest == null || guest.vid == null || !guest.accessToken) {
        if (!challenged) throw new Error("游客预登录没有返回登录态，也没有触发验证码");
        if (allowCaptcha === false) throw new Error("扫码临时会话被要求安全验证，请稍后重新扫码");
        j.longToast("已触发游客安全验证，验证成功后会自动继续登录");
        captcha = wrGetCaptcha(j);
        j.longToast("已取得验证码结果，正在完成游客登录...");
        var loginResponse = j.post("https://i.weread.qq.com/guestLogin", guestBodyText,
            wrLoginHeaderMap(userAgent, captcha.ticket, captcha.randstr), 30000);
        guest = wrResponseJson(loginResponse, "游客登录").data;
    }
    if (guest.vid == null || !guest.accessToken) throw new Error("游客登录没有返回 vid/accessToken");
    return {guest:guest, captcha:captcha};
}
function wrGuestLogin(j, src, input) {
    var userAgent = wrInputValue(input, "User-Agent") || wrValue(src, "User-Agent") || WR_DEFAULT_USER_AGENT;
    var state = wrDeviceState(src, input);
    var session = wrAcquireGuestSession(j, src, input, userAgent, state);
    var guest = session.guest, captcha = session.captcha;
    var verifyHeaders = wrBaseHeaderObject(userAgent);
    verifyHeaders.vid = String(guest.vid);
    verifyHeaders.accessToken = String(guest.accessToken);
    if (captcha.ticket) verifyHeaders.wr_ticket = String(captcha.ticket);
    if (captcha.randstr) verifyHeaders.wr_randstr = String(captcha.randstr);
    var verifyUrl = "https://i.weread.qq.com/store/search?count=1&type=0&keyword=%E6%B5%8B%E8%AF%95&v=2&scope=17&maxIdx=0";
    var verifyResponse = j.get(verifyUrl, wrMap(verifyHeaders), 30000);
    var verified = wrResponseJson(verifyResponse, "游客阅读状态").data;
    if (verified.errcode != null && Number(verified.errcode) != 0) {
        throw new Error("游客阅读状态失败，错误码 " + verified.errcode);
    }
    var saved = wrSaveGuestLogin(j, src, input, state, userAgent, guest, captcha);
    var persistedResponse = j.get(verifyUrl, wrHeaderMap(src), 30000);
    var persisted = wrResponseJson(persistedResponse, "游客登录保存验证").data;
    if (persisted.errcode != null && Number(persisted.errcode) != 0) {
        throw new Error("游客登录保存验证失败，错误码 " + persisted.errcode);
    }
    j.upLoginData(wrMap({vid:saved.vid, accessToken:saved.accessToken, "User-Agent":saved["User-Agent"],
        "游客登录（需验证码）":"游客登录验证成功"}));
    var message = "游客登录验证成功，可以阅读正文";
    try { j.toast(message); } catch (ignoreShortToast) {}
    j.longToast(message);
    return message;
}
function wrSaveQrLogin(j, src, input, state, userAgent, loginData) {
    var saved = {
        "vid": String(loginData.vid),
        "accessToken": String(loginData.accessToken),
        "User-Agent": userAgent,
        "段评开关": wrInputToggle(input, src, "段评开关", "🔳"),
        "章评开关": wrInputToggle(input, src, "章评开关", "🔳"),
