      var item = bubbles[i] || {};
      var pid = String(item.p || '');
      if (!pid) continue;
      var count = Number(item.c || 0);
      if (count > 0 || item.gid || item.gtxt) {
        marks[pid] = {count: count, hot: String(item.hot || '') == '1', gid: String(item.gid || ''), gtxt: String(item.gtxt || '')};
      }
