function showFanqieComment(url, title) {
    let { java } = this;
    title = title || '本章说';
    let pageUrl = String(url || '');
    if (!pageUrl) {
        try { java.toast('评论地址为空，请刷新本章'); } catch (e) {}
        return;
    }
    let islyc = this.checkEnv();
    try {
        if (islyc == '轻阅读') {
