  font-weight: 700;
  position: relative;
}

.highlight::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, var(--color-primary), var(--color-primary-light));
  border-radius: 2px;
}

.highlight-orange {
  color: #f97316;
  font-weight: 700;
}

.highlight-blue {
  color: #3b82f6;
  font-weight: 700;
}

.highlight-purple {
  color: #a855f7;
  font-weight: 700;
}

.highlight-red {
  color: #ef4444;
  font-weight: 700;
}

/* 选择器样式 */
.select-wrapper {
  position: relative;
  flex-shrink: 0;
}

.select-wrapper select {
  appearance: none;
  -webkit-appearance: none;
  padding: 10px 34px 10px 14px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--bg-card);
  border: 2px solid var(--border-color);
  border-radius: 10px;
  cursor: pointer;
  min-width: 110px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.select-wrapper select:hover {
  border-color: var(--color-primary);
}

.select-wrapper select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(45, 157, 120, 0.1);
}

.select-wrapper::after {
  content: '\\f078';
  font-family: 'Font Awesome 6 Free';
  font-weight: 900;
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-secondary);
  pointer-events: none;
  font-size: 13px;
  transition: transform 0.3s ease;
}

.select-wrapper:hover::after {
  transform: translateY(-50%) rotate(180deg);
}

/* 提示文案样式 */
.tip-alert {
  background: linear-gradient(135deg, rgba(255, 193, 7, 0.12) 0%, rgba(255, 152, 0, 0.08) 100%);
  border: 1px solid rgba(255, 193, 7, 0.25);
  border-radius: 16px;
  padding: 16px 18px;
  margin: 20px;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  box-shadow: 0 4px 16px rgba(255, 193, 7, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.8);
  position: relative;
  overflow: hidden;
}

.tip-alert::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 100px;
  height: 100px;
  background: rgba(255, 193, 7, 0.1);
  border-radius: 50%;
}

.tip-alert i {
  color: #f97316;
  font-size: 22px;
  flex-shrink: 0;
  margin-top: 2px;
  position: relative;
  z-index: 1;
}

.tip-alert p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin: 0;
  position: relative;
  z-index: 1;
}

.tip-alert .highlight-text {
  color: #ea580c;
  font-weight: 700;
}

/* 响应式 */
@media (max-width: 600px) {
  .container {
    padding: 16px 12px;
  }

  .main-card {
    border-radius: 20px;
  }

  .tab-content {
    padding: 16px;
  }

  .tip-alert {
    margin: 16px;
    padding: 14px 16px;
  }

  .source-subtabs {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .source-options {
    grid-template-columns: repeat(auto-fill, minmax(105px, 1fr));
    gap: 10px;
  }

  .setting-item {
    padding: 16px;
  }

  .setting-title {
    font-size: 15px;
  }

  .setting-desc {
    font-size: 12px;
  }
}

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: var(--bg-elevated);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb {
  background: var(--text-tertiary);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-secondary);
}
